{
  "1": {
    "class_type": "CheckpointLoaderSimple",
    "inputs": {
      "ckpt_name": "animagineXL_anime_v3.safetensors"
    }
  },
  "2": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "clip": ["1", 1],
      "text": "traditional 1990s cel animation key visual, sneaker caught mid-air above a city rooftop, laces lifting in the wind, skyline soft in the background, clean ink outlines, flat cel shading with one shadow and one highlight tone, quiet and luxurious mood, bright high-key studio light on a pale backdrop, deep navy with a single coral accent, subject clearly readable at thumbnail size, calm negative space around it, no watermarks, no extra logos, no borders or frames, no 3D-render look, square composition"
    }
  },
  "3": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "clip": ["1", 1],
      "text": "watermark, logo, border, frame, 3D render, photorealistic, blurry, low quality, extra objects, text, signature"
    }
  },
  "4": {
    "class_type": "EmptyLatentImage",
    "inputs": {
      "width": 1024,
      "height": 1024,
      "batch_size": 1
    }
  },
  "5": {
    "class_type": "KSampler",
    "inputs": {
      "model": ["1", 0],
      "seed": 42,
      "steps": 30,
      "cfg": 7.0,
      "sampler_name": "euler",
      "scheduler": "normal",
      "positive": ["2", 0],
      "negative": ["3", 0],
      "latent_image": ["4", 0],
      "denoise": 1.0
    }
  },
  "6": {
    "class_type": "VAEDecode",
    "inputs": {
      "samples": ["5", 0],
      "vae": ["1", 2]
    }
  },
  "7": {
    "class_type": "ImageScale",
    "inputs": {
      "image": ["6", 0],
      "upscale_method": "lanczos",
      "width": 1080,
      "height": 1080,
      "crop": "disabled"
    }
  },
  "8": {
    "class_type": "SaveImage",
    "inputs": {
      "images": ["7", 0],
      "filename_prefix": "northwind_coffee_keyvisual"
    }
  }
}

